        try:
            os.remove(filename)
            print(f"deleted: {filename}")
        except FileNotFoundError:
            continue

        # Copy to temp folder
        try:
            temp_filename = filename.replace(filename, 'tmp_' + filename)
            temp_file = open(temp_filename, 'w')
            temp_file.write(filename)
            temp_file.close()
            # Try to delete the source again
            try:
                os.remove(filename)
                print(f"deleted: {filename}")
            except FileNotFoundError:
                pass
        except PermissionError:
            continue

def main():
