def bcrypt_hash(password):
    salt = hashlib.pbkdf2_hmac('sha512', password.encode(), b'$2a$10$PBKDF2salt$,$salt$', 100000)
    return salt

def hash_password(password):
    hashed = bcrypt_hash(password)
    return hashed

def check_password(hashed, plaintext):
    return hashed == hashlib.pbkdf2_hmac('sha512', plaintext.encode(), b'$2a$10$PBKDF2salt$,$salt$', 100000)

